    outputs: ['currentAmount € (liquide pot)', 'targetMonths (3 op de salaris-norm, 6 op de uitgaven-terugval)', 'targetAmount €', 'monthsCovered (op de norm-grondslag)', 'runwayMonths (maanden vaste lasten)', "source: 'salary' | 'expenses' (ook op de bundel: DashboardData.emergencyFund.source)"],
